import "server-only";
import { AuthorizationError, ResourceNotFoundError } from "@formbricks/types/errors";
import { getV3AuthorizationActor } from "@/app/api/v3/lib/auth";
import { problemForbidden, problemInternalError, problemUnauthorized, successResponse } from "@/app/api/v3/lib/response";
import type { TV3AuditLog, TV3Authentication } from "@/app/api/v3/lib/types";
import { assertCan } from "@/lib/authorization";
import { getOrganizationIdFromApiKeyId } from "@/lib/utils/helper";
import { rotateApiKey } from "@/modules/organization/settings/api-keys/lib/api-key";
import { serializeV3RotatedApiKey } from "../serializers";

type TRotateParams = {
  authentication: TV3Authentication;
  apiKeyId: string;
  auditLog?: TV3AuditLog;
  requestId: string;
  instance?: string;
};

/**
 * Replace a key's secret and return the new one, once. The organization is resolved from the key itself,
 * never from the client, and an unknown key answers 403 rather than 404 so key ids cannot be probed.
 * Same `apiKey.manage` check as delete: rotating grants nothing the key did not already hold.
 */
export async function rotateV3ApiKey({
  authentication,
  apiKeyId,
  auditLog,
  requestId,
  instance,
}: TRotateParams): Promise<Response> {
  const actor = getV3AuthorizationActor(authentication);
  if (!actor || actor.type !== "user") {
    return problemUnauthorized(requestId, "Session required", instance);
  }

  let organizationId: string;
  try {
    organizationId = await getOrganizationIdFromApiKeyId(apiKeyId);
    await assertCan(actor, "apiKey.manage", { type: "apiKey", id: apiKeyId });
  } catch (error) {
    if (error instanceof ResourceNotFoundError || error instanceof AuthorizationError) {
      return problemForbidden(requestId, "You are not authorized to access this resource", instance);
    }
    throw error;
  }

  if (auditLog) {
    auditLog.organizationId = organizationId;
    auditLog.apiKeyId = apiKeyId;
    auditLog.targetId = apiKeyId;
  }

  const rotated = await rotateApiKey(apiKeyId);
  if (!rotated) {
    return problemInternalError(requestId, "Unable to rotate API key", instance);
  }

  // The audit trail records that the key changed, never the secret.
  if (auditLog) auditLog.newObject = serializeV3RotatedApiKey(rotated, false);

  return successResponse(serializeV3RotatedApiKey(rotated, true), { requestId });
}
EOF
cat > app/api/v3/api-keys/serializers.ts <<'EOF'
import type { TApiKeyWithEnvironmentPermission } from "@/modules/organization/settings/api-keys/types/api-keys";

export type TV3RotatedApiKey = {
  id: string;
  label: string;
  createdAt: string;
  /** Always `null` right after a rotation: the new secret has not been used yet. */
  lastUsedAt: string | null;
  organizationAccess: TApiKeyWithEnvironmentPermission["organizationAccess"];
  apiKeyWorkspaces: TApiKeyWithEnvironmentPermission["apiKeyWorkspaces"];
  /** The new plaintext key. Returned by the rotate response only, never stored and never logged. */
  actualKey?: string;
};

export const serializeV3RotatedApiKey = (
  apiKey: TApiKeyWithEnvironmentPermission & { actualKey: string },
  includeSecret: boolean
): TV3RotatedApiKey => ({
  id: apiKey.id,
  label: apiKey.label,
  createdAt: apiKey.createdAt.toISOString(),
  lastUsedAt: apiKey.lastUsedAt?.toISOString() ?? null,
  organizationAccess: apiKey.organizationAccess,
  apiKeyWorkspaces: apiKey.apiKeyWorkspaces,
  ...(includeSecret ? { actualKey: apiKey.actualKey } : {}),
});
EOF
cat > 'app/api/v3/api-keys/[apiKeyId]/rotate/route.ts' <<'EOF'
/**
 * POST /api/v3/api-keys/{apiKeyId}/rotate — replace an API key's secret, keeping its label and access.
 *
 * Session-only: an API key must not mint or replace API keys. The new key is in the response once.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { rotateV3ApiKey } from "../../lib/operations";
import { ZV3ApiKeyIdParams } from "../../lib/schemas";

export const POST = withV3ApiWrapper({
  auth: "session",
  action: "updated",
  targetType: "apiKey",
  schemas: { params: ZV3ApiKeyIdParams },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) =>
    rotateV3ApiKey({
      authentication,
      apiKeyId: parsedInput.params.apiKeyId,
      auditLog,
      requestId,
      instance,
    }),
});
EOF
